package dev.joblessreincarnation.magic;

import com.mojang.authlib.GameProfile;
import dev.joblessreincarnation.JoblessReincarnation;
import dev.joblessreincarnation.registry.*;
import dev.joblessreincarnation.npc.*;
import dev.joblessreincarnation.training.*;
import dev.joblessreincarnation.network.CourseRecordsResponsePayload;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.effect.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.level.BlockEvent;
import net.neoforged.neoforge.event.tick.LevelTickEvent;
import net.neoforged.neoforge.gametest.*;
import java.util.*;
import java.util.function.Consumer;

@GameTestHolder(JoblessReincarnation.MOD_ID)
@PrefixGameTestTemplate(false)
public class IcicleGameTests {
    private static final class Caster extends FakePlayer {Caster(ServerLevel level){super(level,new GameProfile(UUID.randomUUID(),"Ice"+UUID.randomUUID().toString().substring(0,8)));}void tickUse(){if(isUsingItem())updateUsingItem(getUseItem());}}
    private static Caster caster(GameTestHelper h){var p=new Caster(h.getLevel());p.getAbilities().instabuild=false;p.setItemInHand(InteractionHand.MAIN_HAND,ModContent.TRAINING_STAFF.get().getDefaultInstance());p.getData(ModAttachments.KNOWLEDGE).learn(IcicleSpell.SPELL);p.setData(ModAttachments.MANA,ManaData.full(100));p.setPos(h.absoluteVec(new Vec3(8.5,2,3.5)));Vec3 d=h.absoluteVec(new Vec3(8.5,2,8.5)).subtract(p.getEyePosition());p.setYRot((float)Math.toDegrees(Math.atan2(-d.x,d.z)));p.setXRot((float)-Math.toDegrees(Math.atan2(d.y,d.horizontalDistance())));return p;}
    @SuppressWarnings("unchecked") private static void age(IcicleFieldEntity f,int ticks){try{var a=IcicleFieldEntity.class.getDeclaredField("START");a.setAccessible(true);f.getEntityData().set((EntityDataAccessor<Long>)a.get(null),f.level().getGameTime()-ticks);}catch(Exception e){throw new RuntimeException(e);}}
    private static IcicleFieldEntity field(GameTestHelper h,FakePlayer p){var f=new IcicleFieldEntity(h.getLevel(),p,h.absoluteVec(new Vec3(8.5,2,8.5)));h.assertTrue(h.getLevel().addFreshEntity(f),"field admitted");IcicleFields.activate(f);age(f,10);return f;}
    private static void tick(GameTestHelper h){IcicleFields.tick(new LevelTickEvent.Post(()->true,h.getLevel()));}
    private static net.minecraft.world.entity.monster.Husk mob(GameTestHelper h,double x,double z){var e=EntityType.HUSK.create(h.getLevel());e.setPos(h.absoluteVec(new Vec3(x,2,z)));e.setNoAi(true);e.setOnGround(true);h.getLevel().addFreshEntity(e);return e;}
    private static void finish(GameTestHelper h,IcicleFieldEntity f){f.discard();tick(h);}
    @GameTest(template="empty",batch="icicleF01") public static void paidCastHasOneFieldAndNoNinthTome(GameTestHelper h){var p=caster(h);h.assertTrue(IcicleSpell.cast(p),"ground release succeeds");h.assertValueEqual(p.getData(ModAttachments.MANA).mana(),70,"pays 30 once");h.assertValueEqual(SpellCatalog.ICICLE_FIELD.practiceCount(p),1,"practice increments once");h.assertFalse(IcicleSpell.cast(p),"cooldown prevents duplicate");var fields=h.getLevel().getEntitiesOfClass(IcicleFieldEntity.class,h.getBounds(),f->f.owner()==p);h.assertValueEqual(fields.size(),1,"one paid area");h.assertFalse(fields.getFirst().shouldBeSaved(),"temporary area never reloads a paid spell");h.assertTrue(SpellCatalog.ICICLE_FIELD.tomeItem()==null,"no new textbook");h.assertValueEqual(Arrays.stream(SpellCatalog.values()).filter(s->s.tomeItem()!=null).count(),8L,"eight old tomes");finish(h,fields.getFirst());h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void dryColdNeverDamagesAndPreservesOtherSlow(GameTestHelper h){var p=caster(h);var f=field(h,p);var e=mob(h,8.5,8.5);e.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN,200,1));float hp=e.getHealth();tick(h);h.assertTrue(e.getAttribute(Attributes.MOVEMENT_SPEED).hasModifier(IcicleFields.SLOW_ID),"our cold slows");h.assertValueEqual(e.getHealth(),hp,"dry cold has no damage");h.assertValueEqual(e.getTicksFrozen(),0,"our overlay must not introduce vanilla frozen counters");finish(h,f);h.assertFalse(e.getAttribute(Attributes.MOVEMENT_SPEED).hasModifier(IcicleFields.SLOW_ID),"our slow removed");h.assertTrue(e.hasEffect(MobEffects.MOVEMENT_SLOWDOWN),"other potion preserved");e.discard();h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void wetTargetNovaOnlyOnceEvenWithOverlappingRecast(GameTestHelper h){var p=caster(h);var f=field(h,p);var e=mob(h,8.5,8.5);IcicleWet.splash(e,p);float hp=e.getHealth();tick(h);h.assertValueEqual(e.getHealth(),hp-2,"wet combo deals 2 points");h.assertValueEqual(e.getAttribute(Attributes.MOVEMENT_SPEED).getModifier(IcicleFields.SLOW_ID).amount(),-.75,"strong slow not root");tick(h);var next=field(h,p);tick(h);h.assertValueEqual(e.getHealth(),hp-2,"no repeated/stacking damage in 60 tick cold window");f.discard();next.discard();e.discard();tick(h);h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void pvpOffProtectsOthersButSelfStillEligible(GameTestHelper h){var p=caster(h);var other=caster(h);boolean old=h.getLevel().getServer().isPvpAllowed();try{h.getLevel().getServer().setPvpAllowed(false);h.assertFalse(IcicleFields.eligible(p,other),"PvP off protects other player");h.assertTrue(IcicleFields.eligible(p,p),"caster is not selectively immune");}finally{h.getLevel().getServer().setPvpAllowed(old);}h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void wallsStopCold(GameTestHelper h){var p=caster(h);var f=field(h,p);var e=mob(h,10.5,8.5);for(int y=2;y<=4;y++)for(int z=6;z<=11;z++)h.setBlock(new BlockPos(9,y,z),Blocks.STONE);tick(h);h.assertFalse(e.getAttribute(Attributes.MOVEMENT_SPEED).hasModifier(IcicleFields.SLOW_ID),"cold cannot pass solid wall");finish(h,f);e.discard();h.succeed();}
    private static void water(GameTestHelper h){for(int x=6;x<=10;x++)for(int z=6;z<=10;z++)h.setBlock(new BlockPos(x,1,z),Blocks.WATER);}
    @GameTest(template="empty",batch="icicleF01") public static void sourceWaterFreezesAndFireImpactMeltsOnlyOwnedIce(GameTestHelper h){water(h);var p=caster(h);var f=field(h,p);tick(h);h.assertTrue(f.frozen.size()>=6,"usable water surface freezes");var cell=f.frozen.iterator().next();h.assertTrue(h.getLevel().getBlockState(cell).is(Blocks.FROSTED_ICE),"actual frozen source is frosted ice");IcicleFields.heatAt(h.getLevel(),f.position().add(0,.3,0),p);h.assertTrue(h.getLevel().getBlockState(cell).is(Blocks.WATER),"heat returns actual owned cell to water");h.assertFalse(f.activeAt(h.getLevel().getGameTime()),"heat ends active cooling");finish(h,f);h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void protectedPlacementRollsBackWithoutDestroyingWater(GameTestHelper h){water(h);var p=caster(h);var f=field(h,p);Consumer<BlockEvent.EntityPlaceEvent> deny=e->{if(e.getEntity()==p)e.setCanceled(true);};NeoForge.EVENT_BUS.addListener(deny);try{tick(h);h.assertTrue(f.frozen.isEmpty(),"denied cells are not counted");h.assertBlockPresent(Blocks.WATER,new BlockPos(8,1,8));}finally{NeoForge.EVENT_BUS.unregister(deny);finish(h,f);}h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void knownProgressSurvivesNewPrivateCourseAndSave(GameTestHelper h){var p=caster(h);p.getData(ModAttachments.KNOWLEDGE).learn(SpellCatalog.WATER_BOLT.id());p.getData(ModAttachments.KNOWLEDGE).practice(SpellCatalog.WATER_BOLT.id());p.setData(ModAttachments.ICICLE_COURSE,new IcicleCourse(2,6));var data=p.saveWithoutId(new CompoundTag());var loaded=caster(h);loaded.load(data);h.assertValueEqual(IcicleLesson.progress(loaded),new IcicleCourse(2,6),"course survives save");h.assertValueEqual(SpellCatalog.WATER_BOLT.practiceCount(loaded),1,"old spell count preserved");var blank=caster(h);h.assertValueEqual(IcicleLesson.progress(blank),IcicleCourse.NEW,"old/missing field defaults new");h.assertFalse(IcicleLesson.qualified(blank),"knowledge alone is not graduation qualification");h.assertValueEqual(CourseRecordsResponsePayload.fromPlayer(7,p).icicle().primary(),6,"private read-only snapshot");h.assertValueEqual(IcicleLesson.progress(p),new IcicleCourse(2,6),"read does not award progress");h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void wetDummyRequiresOwnWaterContactAndCorrectCourseOrder(GameTestHelper h){var p=caster(h);var other=caster(h);var d=ModContent.PRACTICE_DUMMY.get().create(h.getLevel());d.setPos(h.absoluteVec(new Vec3(8.5,2,8.5)));d.setOwnerId(p.getUUID());h.assertTrue(h.getLevel().addFreshEntity(d),"dummy admitted");p.setData(ModAttachments.ICICLE_COURSE,new IcicleCourse(1,0));IcicleWet.splash(d,p);IcicleLesson.nova(p,d);h.assertValueEqual(IcicleLesson.progress(p).stage(),1,"cannot skip water stage");IcicleLesson.frozen(p,6);IcicleWet.dry(d);IcicleWet.splash(d,other);h.assertFalse(IcicleWet.contact(d,other.getUUID()),"another player's water cannot claim this dummy");var f=field(h,p);tick(h);h.assertValueEqual(IcicleLesson.progress(p).stage(),2,"dry dummy gives no credit");var bolt=new WaterBolt(h.getLevel(),p);bolt.onHitEntity(new EntityHitResult(d));h.assertTrue(IcicleWet.contact(d,p.getUUID()),"real projectile hit wets a non-living prop");tick(h);h.assertValueEqual(IcicleLesson.progress(p).stage(),3,"own combo advances once");h.assertFalse(IcicleLesson.qualified(p),"must return to teacher");finish(h,f);d.discard();h.succeed();}

    @GameTest(template="empty",batch="icicleF01") public static void invalidAimAndNoManaKeepOldFieldAndChargeNothing(GameTestHelper h){var p=caster(h);var old=field(h,p);p.setXRot(-90);h.assertFalse(IcicleSpell.cast(p),"no target cannot cast");h.assertTrue(old.activeAt(h.getLevel().getGameTime()),"failed replacement leaves old area");h.assertValueEqual(p.getData(ModAttachments.MANA).mana(),100,"no target is free");p.setData(ModAttachments.MANA,ManaData.full(10));h.assertFalse(IcicleSpell.cast(p),"cannot afford");h.assertValueEqual(SpellCatalog.ICICLE_FIELD.practiceCount(p),0,"failed cast earns no practice");h.assertFalse(IcicleGround.loaded(h.getLevel(),new Vec3(Double.NaN,0,0),Vec3.ZERO),"invalid ray rejected before traversal");finish(h,old);h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void ownColdIsRealAndRemovalClearsOnlyItsModifier(GameTestHelper h){var p=caster(h);var f=field(h,p);p.setPos(f.position());h.getLevel().addNewPlayer(p);h.assertTrue(h.getLevel().getEntity(p.getUUID())==p,"self fixture is actually world-registered");tick(h);h.assertTrue(p.getAttribute(Attributes.MOVEMENT_SPEED).hasModifier(IcicleFields.SLOW_ID),"owner also cold");IcicleFields.endOwner(p);tick(h);h.assertTrue(f.isRemoved(),"owner cleanup removes transient area");h.assertFalse(p.getAttribute(Attributes.MOVEMENT_SPEED).hasModifier(IcicleFields.SLOW_ID),"no permanent slow after cleanup");p.discard();h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void waterloggedAndFlowingWaterAreNotConverted(GameTestHelper h){var p=caster(h);var f=field(h,p);h.setBlock(new BlockPos(8,1,8),Blocks.WATER.defaultBlockState().setValue(net.minecraft.world.level.block.LiquidBlock.LEVEL,1));h.setBlock(new BlockPos(9,1,8),Blocks.OAK_SLAB.defaultBlockState().setValue(net.minecraft.world.level.block.SlabBlock.WATERLOGGED,true));tick(h);h.assertTrue(f.frozen.isEmpty(),"no source water so nothing replaced");h.assertBlockPresent(Blocks.WATER,new BlockPos(8,1,8));h.assertBlockPresent(Blocks.OAK_SLAB,new BlockPos(9,1,8));finish(h,f);h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void fireExtinguishHonoursProtectionAndStillDissipatesCold(GameTestHelper h){var p=caster(h);var f=field(h,p);h.setBlock(new BlockPos(9,2,8),Blocks.FIRE);Consumer<BlockEvent.BreakEvent> deny=e->{if(e.getPlayer()==p)e.setCanceled(true);};NeoForge.EVENT_BUS.addListener(deny);try{tick(h);h.assertBlockPresent(Blocks.FIRE,new BlockPos(9,2,8));h.assertFalse(f.activeAt(h.getLevel().getGameTime()),"protected heat still dissipates field");}finally{NeoForge.EVENT_BUS.unregister(deny);finish(h,f);}h.succeed();}
    private static RoxyTutorEntity teacher(GameTestHelper h){var t=ModContent.ROXY_TUTOR.get().create(h.getLevel());t.setPos(h.absoluteVec(new Vec3(8.5,2,5.5)));t.setNoAi(true);h.getLevel().addFreshEntity(t);return t;}
    private static FakePlayer student(GameTestHelper h){var p=caster(h);p.setData(ModAttachments.KNOWLEDGE,new MagicKnowledge());p.getData(ModAttachments.KNOWLEDGE).learn(SpellCatalog.WATER_BOLT.id());p.setShiftKeyDown(true);return p;}
    @GameTest(template="empty",batch="icicleF01",timeoutTicks=70) public static void teachingWaitsForActualDemonstrationThenGrantsKnowledge(GameTestHelper h){var p=student(h);var t=teacher(h);h.assertTrue(IcicleLesson.interact(p,t),"asks actual teacher");h.assertFalse(SpellCatalog.ICICLE_FIELD.knows(p),"not granted at first click");h.runAfterDelay(45,()->{h.assertTrue(SpellCatalog.ICICLE_FIELD.knows(p),"completed 40 tick demonstration teaches");h.assertValueEqual(IcicleLesson.progress(p).stage(),1,"water exercise now active");h.assertFalse(IcicleLesson.qualified(p),"learning not graduation completion");t.discard();p.discard();h.succeed();});}
    @GameTest(template="empty",batch="icicleF01",timeoutTicks=70) public static void walkingAwayFromDemonstrationDoesNotTeach(GameTestHelper h){var p=student(h);var t=teacher(h);IcicleLesson.interact(p,t);p.setPos(p.position().add(20,0,0));h.runAfterDelay(45,()->{h.assertFalse(SpellCatalog.ICICLE_FIELD.knows(p),"cannot walk away and earn it");h.assertValueEqual(IcicleLesson.progress(p),IcicleCourse.NEW,"aborted demonstration preserves empty course");t.discard();p.discard();h.succeed();});}
    @GameTest(template="empty",batch="icicleF01") public static void onlyReturningAfterBothExercisesCompletesCourse(GameTestHelper h){var p=caster(h);var t=teacher(h);p.setShiftKeyDown(true);p.setData(ModAttachments.ICICLE_COURSE,new IcicleCourse(2,6));IcicleLesson.interact(p,t);h.assertFalse(IcicleLesson.qualified(p),"teacher cannot skip combo");p.setData(ModAttachments.ICICLE_COURSE,new IcicleCourse(3,6));p.setShiftKeyDown(false);p.getData(ModAttachments.CASTING).select(SpellCatalog.WATER_BOLT.id());IcicleLesson.interact(p,t);h.assertTrue(IcicleLesson.qualified(p),"ordinary staff conversation completes ready course even after changing selection");t.discard();h.succeed();}

    @GameTest(template="empty",batch="icicleF01") public static void waterWithSwimmerIsNotReplacedBySolidIce(GameTestHelper h){water(h);var p=caster(h);var f=field(h,p);var e=mob(h,8.5,8.5);e.setPos(h.absoluteVec(new Vec3(8.5,1.3,8.5)));tick(h);h.assertBlockPresent(Blocks.WATER,new BlockPos(8,1,8));h.assertTrue(f.frozen.size()>=6,"nearby unobstructed water may still freeze");finish(h,f);e.discard();h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void teamProtectionWinsEvenWithPvpEnabled(GameTestHelper h){var p=caster(h);var other=caster(h);var board=h.getLevel().getScoreboard();var team=board.addPlayerTeam("ice"+p.getUUID().toString().substring(0,8));boolean old=h.getLevel().getServer().isPvpAllowed();try{h.getLevel().getServer().setPvpAllowed(true);team.setAllowFriendlyFire(true);board.addPlayerToTeam(p.getScoreboardName(),team);board.addPlayerToTeam(other.getScoreboardName(),team);h.assertFalse(IcicleFields.eligible(p,other),"same team remains protected");}finally{board.removePlayerTeam(team);h.getLevel().getServer().setPvpAllowed(old);}h.succeed();}

    private static void chant(Caster p,int ticks){p.getData(ModAttachments.CASTING).select(IcicleSpell.SPELL);ModContent.TRAINING_STAFF.get().use(p.level(),p,InteractionHand.MAIN_HAND);for(int n=0;n<ticks;n++)p.tickUse();}
    @GameTest(template="empty",batch="icicleF01") public static void actualOverdraftCastPaysOnceWithoutPracticeCount(GameTestHelper h){var p=caster(h);p.setData(ModAttachments.MANA,new ManaData(0,100,0,0));chant(p,ManaDepletion.confirmTicks(p,SpellCatalog.ICICLE_FIELD));h.assertTrue(p.getData(ModAttachments.CASTING).overcasting(),"real hold requests overdraft");p.releaseUsingItem();h.assertTrue(p.getData(ModAttachments.MANA).overcastLocked(),"valid area commits exhaustion");h.assertValueEqual(SpellCatalog.ICICLE_FIELD.practiceCount(p),0,"overdraft gives no practice");var fs=h.getLevel().getEntitiesOfClass(IcicleFieldEntity.class,h.getBounds(),f->f.owner()==p);h.assertValueEqual(fs.size(),1,"one committed area");finish(h,fs.getFirst());h.succeed();}
    @GameTest(template="empty",batch="icicleF01") public static void invalidOverdraftAndSneakCancelAreFree(GameTestHelper h){var p=caster(h);p.setData(ModAttachments.MANA,new ManaData(0,100,0,0));p.setXRot(-90);chant(p,ManaDepletion.confirmTicks(p,SpellCatalog.ICICLE_FIELD));p.releaseUsingItem();h.assertFalse(p.getData(ModAttachments.MANA).overcastLocked(),"no terrain means no exhaustion");p.setData(ModAttachments.MANA,ManaData.full(100));p.setXRot(30);chant(p,SpellCatalog.ICICLE_FIELD.chantTicks(p));p.setShiftKeyDown(true);p.releaseUsingItem();h.assertValueEqual(p.getData(ModAttachments.MANA).mana(),100,"sneak cancels without payment");h.assertTrue(h.getLevel().getEntitiesOfClass(IcicleFieldEntity.class,h.getBounds(),f->f.owner()==p).isEmpty(),"no field from rejected release");h.succeed();}

    @GameTest(template="empty",batch="icicleF01") public static void retiredPlayerObjectCannotEraseReplacementPlayersField(GameTestHelper h){var old=caster(h);var first=field(h,old);var next=new FakePlayer(h.getLevel(),old.getGameProfile());var replacement=field(h,next);IcicleFields.endOwner(old);h.assertTrue(first.isRemoved(),"retired object's field is cleared");h.assertFalse(replacement.isRemoved(),"same UUID new player object keeps its paid field");h.assertTrue(IcicleFields.registered(replacement),"replacement ownership stays registered");finish(h,replacement);h.succeed();}

    @GameTest(template="empty",batch="icicleF01") public static void realWaterProjectileSweepCanWetOnlyItsOwnersDummy(GameTestHelper h){var p=caster(h);var stranger=caster(h);var d=ModContent.PRACTICE_DUMMY.get().create(h.getLevel());d.setOwnerId(p.getUUID());d.setPos(h.absoluteVec(new Vec3(8.5,2,8.5)));h.getLevel().addFreshEntity(d);h.assertFalse(d.canBeHitByProjectile(),"generic projectile immunity stays unchanged");var wrong=new WaterBolt(h.getLevel(),stranger);h.assertFalse(wrong.canHitEntity(d),"cannot target another student's dummy");var bolt=new WaterBolt(h.getLevel(),p);bolt.setPos(p.getEyePosition());bolt.setDeltaMovement(d.getBoundingBox().getCenter().subtract(bolt.position()).normalize().scale(1.4));h.getLevel().addFreshEntity(bolt);for(int n=0;n<8&&!bolt.isRemoved();n++)bolt.tick();h.assertTrue(bolt.isRemoved(),"real swept movement resolves at the dummy");h.assertTrue(IcicleWet.contact(d,p.getUUID()),"collision path wets the actual prop");d.discard();h.succeed();}

    @GameTest(template="empty",batch="icicleF01",timeoutTicks=30) public static void realTicksKeepOnlyTheIntendedColdSpeedAndPreserveOtherFreezing(GameTestHelper h){var p=caster(h);var f=field(h,p);var e=mob(h,8.5,8.5);double base=e.getAttributeValue(Attributes.MOVEMENT_SPEED);h.runAfterDelay(4,()->{h.assertTrue(Math.abs(e.getAttributeValue(Attributes.MOVEMENT_SPEED)-base*.7)<1e-6,"normal cold is exactly 30 percent after real living ticks");h.assertValueEqual(e.getTicksFrozen(),0,"visual cannot add powder-snow freezing");e.setTicksFrozen(100);tick(h);h.assertValueEqual(e.getTicksFrozen(),100,"existing vanilla freezing left alone");finish(h,f);h.assertValueEqual(e.getTicksFrozen(),100,"ending field does not clear other freezing");e.discard();h.succeed();});}
}
